// Department-led class workshops/seminars only. Uses shared CSV parsing, task
// mapping, command persistence and existing owner-restricted demo authority.
const departmentTaskCSVColumns=['externalId','studentReference','title','due','expectedOutput','responsibility','evidenceRequirement','groupReference','conceptCriterion','skillsCriterion','leadershipCriterion','impactCriterion'];
const departmentTaskCSVDomains={conceptCriterion:'CONCEPT',skillsCriterion:'SKILLS',leadershipCriterion:'LEADERSHIP',impactCriterion:'SDG_IMPACT'};
function departmentTaskCSVSource(p){
 if(!p||p.sourceClub||p.intakeProvenance||p.teamIntakeProvenance||p.specialActivity||!['APPROVED','STARTED','IN_PROGRESS'].includes(p.state)||!activityControlActive(p))return null;
 const plans=db.plans.filter(x=>x.id===p.sourcePlan),plan=plans.length===1?plans[0]:null,item=plan?.items.find(i=>i.id===p.sourceItem);
 if(!plan||!['APPROVED','IN_PROGRESS','COMPLETED'].includes(plan.state)||!item||!['Workshop','Seminar'].includes(item.type)||p.type!==item.type||db.plans.some(x=>x.family===plan.family&&x.version>plan.version&&['APPROVED','IN_PROGRESS','COMPLETED'].includes(x.state))||!plan.department||!plan.course||!plan.semester||!p.members.length||new Set(p.members).size!==p.members.length)return null;
 if((db.activityChanges||[]).some(r=>r.projectId===p.id&&activityChangesPending(r)))return null;
 const roster=[...p.members].sort().map(student=>({student,active:activeParticipant(p,student)}));
 return {plan,item,roster,basis:JSON.stringify({projectId:p.id,sourcePlan:plan.id,sourceVersion:plan.version,department:plan.department,course:plan.course,semester:plan.semester,programme:plan.programme,batch:plan.batch,year:plan.year,item,mentor:p.mentor,coordinator:plan.coordinator,head:plan.head,due:p.due,roster,taskMappings:p.tasks.map(t=>({id:t.id,mappingVersion:t.mappingVersion||0})),ledger:p.departmentTaskCSVLedger||[]}),controlled:(db.planApprovalRecords||[]).some(r=>r.planId===plan.id||r.planId===plan.family)};
}
function departmentTaskCSVDepartment(p){const s=departmentTaskCSVSource(p);return !!s&&canSee(p)&&[s.plan.coordinator,s.plan.head].includes(uid)}
function departmentTaskCSVReader(p){if(!p||p.sourceClub||p.intakeProvenance||p.teamIntakeProvenance||!['Workshop','Seminar'].includes(p.type)||!canSee(p))return false;const plans=db.plans.filter(x=>x.id===p.sourcePlan),plan=plans.length===1?plans[0]:null;return !!plan&&[plan.coordinator,plan.head,p.mentor].includes(uid)}
function departmentTaskCSVBatch(p,id){return (p?.departmentTaskCSVBatches||[]).find(b=>b.id===id)}
function departmentTaskCSVCurrent(p,b){return !!b&&departmentTaskCSVSource(p)?.basis===b.basis}
function departmentTaskCSVValidate(p,row){
 const errors=[],clean=v=>typeof v==='string'&&v.trim()&&v.length<=2000&&!/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(v);
 if(!/^[A-Z0-9][A-Z0-9_.:-]{0,79}$/.test(row.externalId))errors.push('externalId must be a stable 1–80 character task reference');
 if(!p.members.includes(row.studentReference)||!activeParticipant(p,row.studentReference))errors.push('studentReference is not an active member of this event roster');
 if(row.studentReference===p.mentor)errors.push('The assigned mentor cannot assess their own imported task');
 if(!clean(row.title)||row.title.length>120)errors.push('Task title is required, up to 120 characters');
 for(const key of ['expectedOutput','responsibility','evidenceRequirement'])if(!clean(row[key]))errors.push(key+' is required, up to 2000 characters');
 if(typeof row.groupReference!=='string'||row.groupReference.length>2000||/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(row.groupReference))errors.push('Invalid groupReference');
 if(!validWorkDate(row.due)||row.due>p.due)errors.push('Use a valid task deadline no later than the current event deadline');
 if(!Object.keys(departmentTaskCSVDomains).some(k=>row[k]?.trim()))errors.push('At least one observable domain criterion is required');
 for(const key of Object.keys(departmentTaskCSVDomains))if(row[key]&&!clean(row[key]))errors.push('Invalid '+key);
 return errors;
}
function departmentTaskCSVParse(p,text){
 const rows=academicCSV(text),header=rows.shift();if(!header||header.length!==departmentTaskCSVColumns.length||new Set(header).size!==header.length||departmentTaskCSVColumns.some(k=>!header.includes(k)))throw Error('Use exactly the supplied CSV headers.');
 if(!rows.length||rows.length>50)throw Error('Upload 1–50 task rows per batch.');
 const parsed=rows.map((cells,i)=>({line:i+2,cells,row:Object.fromEntries(header.map((k,j)=>[k,cells[j]||'']))}));const counts=new Map();for(const r of parsed){r.row.externalId=r.row.externalId.toUpperCase();counts.set(r.row.externalId,(counts.get(r.row.externalId)||0)+1)}
 return parsed.map(({line,cells,row})=>{const errors=departmentTaskCSVValidate(p,row);if(cells.length!==header.length)errors.push('Column count differs from the header');if(counts.get(row.externalId)>1)errors.push('Duplicate externalId in this file');const binding=JSON.stringify(Object.fromEntries(departmentTaskCSVColumns.map(k=>[k,row[k]]))),old=(p.departmentTaskCSVLedger||[]).filter(x=>x.externalId===row.externalId);if(old.length>1)errors.push('Existing import ledger needs review');if(old.length&&old[0].binding!==binding)errors.push('This event task reference was imported with different content; existing work will not be overwritten');if(old.length&&!p.tasks.some(t=>t.id===old[0].taskId))errors.push('Previously imported task is missing; reconcile its history first');return {line,row,binding,state:errors.length?'INVALID':old.length?'ALREADY_IMPORTED':'VALID',errors,existingTaskId:old[0]?.taskId||null}});
}
function previewDepartmentTaskCSV(event){
 event.preventDefault();const p=current();if(!departmentTaskCSVDepartment(p))return toast('The responsible department must prepare this class-event import.');const f=Object.fromEntries(new FormData(event.target));if(Object.keys(f).some(k=>!['sourceReference','csv'].includes(k))||typeof f.sourceReference!=='string'||!f.sourceReference.trim()||f.sourceReference.length>100)return toast('Provide a stable source reference.');
 const ref=f.sourceReference.trim(),previous=(p.departmentTaskCSVBatches||[]).filter(b=>b.sourceReference===ref).at(-1);if(previous&&['PREVIEWED','SUBMITTED','MENTOR_APPROVED'].includes(previous.state))return toast('Finish or return the current batch for this source reference first.');
 let rows;try{rows=departmentTaskCSVParse(p,f.csv)}catch(e){return toast(e.message)}
 const source=departmentTaskCSVSource(p),batch={id:clubKey('DCSV'),version:1,state:'PREVIEWED',sourceReference:ref,rows,basis:source.basis,rosterSnapshot:JSON.parse(JSON.stringify(source.roster)),academicPeriod:{programme:source.plan.programme,year:source.plan.year,semester:source.plan.semester,course:source.plan.course,batch:source.plan.batch,sourcePlan:source.plan.id,sourcePlanVersion:source.plan.version},by:uid,at:new Date().toISOString(),corrects:previous?.state==='RETURNED'?previous.id:null,history:[]};
 p.departmentTaskCSVBatches??=[];p.departmentTaskCSVBatches.push(batch);log(p,'Department task CSV preview '+batch.id+'; no tasks assigned');closeModal();render();toast('Preview saved. Correct all invalid rows before requesting mentor review.');
}
function submitDepartmentTaskCSV(id,expectedVersion){const p=current(),b=departmentTaskCSVBatch(p,id);if(!departmentTaskCSVDepartment(p)||!b||b.state!=='PREVIEWED'||b.version!==expectedVersion||!departmentTaskCSVCurrent(p,b)||b.rows.some(r=>r.state==='INVALID')||!b.rows.some(r=>r.state==='VALID'))return toast('Use a current, valid preview with new task rows.');b.state='SUBMITTED';b.version++;b.history.push({action:'SUBMITTED',by:uid,at:new Date().toISOString()});log(p,'Department task CSV sent to assigned mentor '+id);render()}
function reviewDepartmentTaskCSV(event,id,expectedVersion){event.preventDefault();const p=current(),b=departmentTaskCSVBatch(p,id),f=Object.fromEntries(new FormData(event.target));if(!departmentTaskCSVReader(p)||uid!==p.mentor||!b||!['PREVIEWED','SUBMITTED'].includes(b.state)||b.version!==expectedVersion||b.by===uid||Object.keys(f).some(k=>!['decision','reason','confirm'].includes(k))||f.confirm!=='yes'||!['MENTOR_APPROVED','RETURNED'].includes(f.decision)||typeof f.reason!=='string'||!f.reason.trim()||f.reason.length>2000)return toast('Independent assigned-mentor review, current batch, reason and confirmation required.');if(f.decision==='MENTOR_APPROVED'&&(b.state!=='SUBMITTED'||!departmentTaskCSVCurrent(p,b)||b.rows.some(r=>r.state==='INVALID')||b.rows.some(r=>r.state==='VALID'&&r.row.studentReference===uid)))return toast('A current valid submitted batch and independent mentor are required.');b.state=f.decision;b.version++;b.review={by:uid,decision:f.decision,reason:f.reason.trim(),at:new Date().toISOString(),basis:b.basis};b.history.push({action:f.decision,...b.review});log(p,'Department task CSV '+f.decision+' '+id);closeModal();render()}
function returnDepartmentTaskCSV(event,id,expectedVersion){event.preventDefault();const p=current(),b=departmentTaskCSVBatch(p,id),f=Object.fromEntries(new FormData(event.target));if(!departmentTaskCSVDepartment(p)||!b||!['PREVIEWED','SUBMITTED','MENTOR_APPROVED'].includes(b.state)||b.version!==expectedVersion||Object.keys(f).some(k=>!['reason','confirm'].includes(k))||f.confirm!=='yes'||typeof f.reason!=='string'||!f.reason.trim()||f.reason.length>2000)return toast('A current unapplied batch, department reason and confirmation are required.');b.state='RETURNED';b.version++;b.history.push({action:'DEPARTMENT_RETURN',by:uid,reason:f.reason.trim(),at:new Date().toISOString()});log(p,'Department task CSV returned without changing existing tasks '+id);closeModal();render()}
function applyDepartmentTaskCSV(event,id,expectedVersion){
 event.preventDefault();const p=current(),b=departmentTaskCSVBatch(p,id),f=Object.fromEntries(new FormData(event.target));if(!departmentTaskCSVDepartment(p)||!b||Object.keys(f).some(k=>!['reason','confirm'].includes(k))||f.confirm!=='yes'||typeof f.reason!=='string'||!f.reason.trim()||f.reason.length>2000)return toast('Department confirmation and a reason are required.');if(b.state==='APPLIED')return toast('This batch was already applied; no duplicate tasks created.');const s=departmentTaskCSVSource(p);
 if(b.state!=='MENTOR_APPROVED'||b.version!==expectedVersion||!departmentTaskCSVCurrent(p,b)||b.review?.by!==p.mentor||b.review?.decision!=='MENTOR_APPROVED'||b.review?.basis!==b.basis||s.controlled||b.rows.some(r=>r.state==='INVALID'))return toast('Use a current mentor-approved batch. Controlled-plan execution authorization remains separate.');
 const fresh=b.rows.filter(r=>r.state==='VALID');if(!fresh.length||fresh.some(r=>departmentTaskCSVValidate(p,r.row).length||(p.departmentTaskCSVLedger||[]).some(l=>l.externalId===r.row.externalId)))return toast('Source rows or roster changed. Request a fresh preview and mentor review.');
 p.departmentTaskCSVLedger??=[];
 for(const entry of fresh){const r=entry.row,fields={title:r.title,assignee:r.studentReference,due:r.due,expectedOutput:r.expectedOutput,responsibility:r.responsibility,evidenceRequirement:r.evidenceRequirement,groupReference:r.groupReference,reason:f.reason.trim()};for(const [column,domain] of Object.entries(departmentTaskCSVDomains))if(r[column]){fields[domain]='yes';fields['criterion_'+domain]=r[column]}
  const t=recordAuthorizedTaskMapping({preventDefault(){}},-1,true,fields);if(!t||p.tasks.filter(x=>x.id===t.id).length!==1)throw Error('Department task mapping could not be committed atomically.');t.academicPeriod=JSON.parse(JSON.stringify(b.academicPeriod));t.sourceDepartmentTaskCSV={batchId:b.id,externalId:r.externalId,sourceReference:b.sourceReference,departmentBy:uid,mentorReviewedBy:b.review.by};t.workState='ASSIGNED';p.departmentTaskCSVLedger.push({externalId:r.externalId,sourceReference:b.sourceReference,binding:entry.binding,taskId:t.id,batchId:b.id,at:new Date().toISOString()});entry.taskId=t.id;
 }
 b.state='APPLIED';b.version++;b.appliedBy=uid;b.appliedAt=new Date().toISOString();b.history.push({action:'APPLIED',by:uid,at:b.appliedAt,reason:f.reason.trim()});log(p,'Department task CSV applied '+id+'; '+fresh.length+' individual task(s)');closeModal();render();toast('Tasks assigned. Students must submit their own work for separate mentor assessment.');
}
function departmentTaskCSVPanel(p){if(!departmentTaskCSVReader(p))return '';const department=departmentTaskCSVDepartment(p);return `<section class="panel"><h2>Department workshop and seminar tasks</h2><p>Department CSV planning → assigned mentor review → department confirmation → individual tasks. The current event roster is retained; uploads cannot enrol students, approve the event, complete work or award credit.</p><p>Use the exact roster account reference. This owner-controlled demo uses fictional roster records; official MIS class-roster validation remains pending.</p>${department?btn('Upload task CSV / preview','departmentTaskCSVForm()')+btn('Download CSV template','downloadDepartmentTaskCSVTemplate()')+btn('Download current roster references','downloadDepartmentTaskCSVRoster()'):''}${(p.departmentTaskCSVBatches||[]).map(b=>`<div class="card"><h3>${esc(b.sourceReference)} · ${esc(b.state)}</h3><p>${esc(b.id)} · v${b.version} · Prepared by ${esc(name(b.by))}${b.corrects?' · Corrects '+esc(b.corrects):''} · ${b.state==='APPLIED'?'Applied; historical source retained':departmentTaskCSVCurrent(p,b)?'Source current':'Source changed — fresh review required'}</p>${tableHTML(['CSV row / task reference','Student / task','Validation'],b.rows.map(r=>[r.line+' / '+esc(r.row.externalId),esc(name(r.row.studentReference))+' · '+esc(r.row.title)+'<details><summary>Individual instructions and criteria</summary><dl>'+departmentTaskCSVColumns.filter(k=>!['externalId','studentReference','title'].includes(k)).map(k=>'<dt>'+esc(k)+'</dt><dd>'+esc(r.row[k]||'Not selected')+'</dd>').join('')+'</dl></details>',esc(r.state)+(r.errors.length?'<p>'+r.errors.map(esc).join('; ')+'</p>':'')]))}${b.review?`<p>Mentor review: ${esc(name(b.review.by))} · ${esc(b.review.decision)} · ${esc(b.review.reason)}</p>`:''}${department&&b.state==='PREVIEWED'&&departmentTaskCSVCurrent(p,b)&&b.rows.every(r=>r.state!=='INVALID')&&b.rows.some(r=>r.state==='VALID')?btn('Send to mentor',`submitDepartmentTaskCSV('${b.id}',${b.version})`):''}${uid===p.mentor&&departmentTaskCSVSource(p)&&['PREVIEWED','SUBMITTED'].includes(b.state)&&b.by!==uid?btn('Review task batch',`departmentTaskCSVReviewForm('${b.id}')`):''}${department&&b.state==='MENTOR_APPROVED'&&departmentTaskCSVCurrent(p,b)&&!departmentTaskCSVSource(p).controlled?btn('Confirm and create tasks',`departmentTaskCSVApplyForm('${b.id}')`):''}${department&&['PREVIEWED','SUBMITTED','MENTOR_APPROVED'].includes(b.state)?btn('Return / replace this batch',`departmentTaskCSVReturnForm('${b.id}')`):''}<details><summary>Batch history</summary>${b.history.map(h=>`<p>${esc(h.action)} · ${esc(name(h.by))} · ${esc(h.reason||'')} · ${esc(h.at)}</p>`).join('')||'<p>Preview only.</p>'}</details></div>`).join('')}</section>`}
function departmentTaskCSVForm(){const p=current();if(!departmentTaskCSVDepartment(p))return;modal(`<h2>Upload individual event tasks</h2><p>${esc(p.title)} · CSV only · maximum 30 KB / 50 data rows. Use a stable source reference; task references are unique within this event. Re-importing identical rows never overwrites existing tasks.</p><form onsubmit="previewDepartmentTaskCSV(event)"><label>Source reference<input name="sourceReference" required maxlength="100"></label><label>Choose CSV file<input id="department-task-csv-file" type="file" accept=".csv,text/csv" onchange="readDepartmentTaskCSVFile(event)"></label><label>CSV content<textarea id="department-task-csv-text" name="csv" required maxlength="30000"></textarea></label><p>File reading is local. Save the preview to validate roster references, deadlines, evidence and assessment domains. No tasks are created at preview.</p><button type="submit">Validate and save preview</button><button type="button" onclick="closeModal()">Cancel</button></form>`)}
async function readDepartmentTaskCSVFile(event){const input=event.target,file=input.files?.[0],target=document.querySelector('#department-task-csv-text'),project=selected;if(!file||!/\.csv$/i.test(file.name)||file.size>30000)return toast('Choose a CSV file no larger than 30 KB.');try{const text=await file.text();if(selected!==project||document.querySelector('#department-task-csv-text')!==target||!departmentTaskCSVDepartment(current()))return;if(text.length>30000)throw Error('CSV exceeds the import limit.');target.value=text;toast('CSV loaded locally. Validate the preview before requesting review.')}catch{return toast('CSV could not be read. No assignments were made.')}}
function departmentTaskCSVReviewForm(id){const p=current(),b=departmentTaskCSVBatch(p,id);if(!b||uid!==p.mentor)return;modal(`<h2>Assigned mentor task review</h2><form onsubmit="reviewDepartmentTaskCSV(event,'${id}',${b.version})"><label>Decision<select name="decision"><option value="MENTOR_APPROVED">Approve task definitions</option><option value="RETURNED">Return for correction</option></select></label><label>Review reason<textarea name="reason" required maxlength="2000"></textarea></label><label><input type="checkbox" name="confirm" value="yes" required>I reviewed the individual duties, outputs, evidence and assessment criteria. This does not complete or grade student work.</label><button type="submit">Record mentor review</button></form>`)}
function departmentTaskCSVApplyForm(id){const b=departmentTaskCSVBatch(current(),id);if(!b||!departmentTaskCSVDepartment(current()))return;modal(`<h2>Department confirmation</h2><form onsubmit="applyDepartmentTaskCSV(event,'${id}',${b.version})"><label>Assignment reason<textarea name="reason" required maxlength="2000"></textarea></label><label><input type="checkbox" name="confirm" value="yes" required>Create only the mentor-approved new rows as individual tasks. Preserve existing work and the event roster.</label><button type="submit">Create individual tasks</button></form>`)}
function departmentTaskCSVReturnForm(id){const b=departmentTaskCSVBatch(current(),id);if(!b||!departmentTaskCSVDepartment(current()))return;modal(`<h2>Return CSV batch</h2><form onsubmit="returnDepartmentTaskCSV(event,'${id}',${b.version})"><label>Correction / return reason<textarea name="reason" required maxlength="2000"></textarea></label><label><input type="checkbox" name="confirm" value="yes" required>Return this batch without deleting its history or changing existing tasks.</label><button type="submit">Return batch</button></form>`)}
function departmentTaskCSVDownload(rows,filename){const cell=v=>{let s=String(v??'');if(/^[=+\-@\t]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadDepartmentTaskCSVTemplate(){if(!departmentTaskCSVDepartment(current()))return;departmentTaskCSVDownload([departmentTaskCSVColumns],'department-event-task-template.csv')}
function downloadDepartmentTaskCSVRoster(){const p=current();if(!departmentTaskCSVDepartment(p))return;departmentTaskCSVDownload([['studentReference','displayName','active'],...departmentTaskCSVSource(p).roster.map(r=>[r.student,name(r.student),r.active?'YES':'NO'])],'department-event-roster-references.csv')}
const departmentTaskCSVPriorOverview=projectOverview;projectOverview=function(p){return departmentTaskCSVPriorOverview(p)+departmentTaskCSVPanel(p)};
// The same class-event assignment policy applies to manual and CSV entry.
// Student project leads keep their existing task workflow outside this route.
const departmentTaskCSVPriorMappingWritable=taskMappingWritable;
taskMappingWritable=function(p){const source=departmentTaskCSVSource(p);if(source)return !source.controlled&&canSee(p)&&(departmentTaskCSVDepartment(p)||uid===p.mentor);if(p?.sourcePlan&&!p.sourceClub&&!p.intakeProvenance&&!p.teamIntakeProvenance&&['Workshop','Seminar'].includes(p.type))return false;return departmentTaskCSVPriorMappingWritable(p)};
const departmentTaskCSVPriorPlansPage=plansPage;
plansPage=function(){const events=db.projects.filter(p=>departmentTaskCSVReader(p));return departmentTaskCSVPriorPlansPage()+(events.length?`<section class="panel"><h2>Workshop and seminar task assignments</h2><p>Strategic event-plan uploads remain separate. For every departmental class workshop or seminar, the responsible department and assigned mentor control individual task assignment. Use the current event roster; student-project proposals continue through Activity Intake.</p>${events.map(p=>{const s=departmentTaskCSVSource(p);return `<div class="row"><div><strong>${esc(p.title)}</strong><p>${esc(s.plan.course)} · Semester ${esc(s.plan.semester)} · ${s.roster.length} roster reference(s)</p></div>${btn('Open event task planning',`openProject('${p.id}')`)}</div>`}).join('')}<div class="buttons">${academicReader()?btn('Student placement / progression CSV',"go('Academic Progression')"):''}</div><p>Placement import supports known student references. New student-master uploads and official MIS synchronization require their separate controlled integration; event rosters and past task mappings retain their snapshots.</p></section>`:'')};
const departmentTaskCSVPriorSaveMapping=saveTaskMapping;
saveTaskMapping=function(event,index=-1){const p=current(),source=departmentTaskCSVSource(p),priorPeriod=p?.tasks[index]?.academicPeriod,task=departmentTaskCSVPriorSaveMapping(event,index);if(task&&source&&!priorPeriod){task.academicPeriod={programme:source.plan.programme,year:source.plan.year,semester:source.plan.semester,course:source.plan.course,batch:source.plan.batch,sourcePlan:source.plan.id,sourcePlanVersion:source.plan.version};save()}return task};
